"""Request-local factual execution ledger; never generated by an LLM."""

import json

from app.core.prompt_security import untrusted_context_message
from app.prompts import format_prompt
from app.agent.results import coder_result_data


def result_metadata(output, generated=None):
    """Keep identifiers and small result metadata, not generated document bodies."""
    try:
        value, _ = json.JSONDecoder().raw_decode(str(output).lstrip())
    except (TypeError, ValueError):
        value = {"excerpt": str(output)[:256]}
    if not isinstance(value, (dict, list)):
        value = {"result_type": type(value).__name__}
    result = {}

    def collect(data, prefix="", depth=0):
        if depth > 4 or len(result) >= 32:
            return
        if isinstance(data, list):
            for index, item in enumerate(data[:16]):
                collect(item, prefix + str(index) + ".", depth + 1)
        elif isinstance(data, dict):
            for key, item in data.items():
                if len(result) >= 32:
                    break
                if isinstance(item, (dict, list)):
                    collect(item, prefix + key + ".", depth + 1)
                elif (
                    key.endswith("_id")
                    or key
                    in {
                        "id",
                        "type",
                        "title",
                        "version",
                        "filename",
                        "status",
                        "question_count",
                        "card_count",
                        "word_count",
                        "excerpt",
                        "result_type",
                    }
                ) and isinstance(item, (str, int, float, bool, type(None))):
                    result[prefix + key] = item[:160] if isinstance(item, str) else item

    collect(value)
    if generated:
        collect(generated, "deliverables.")
    return result


class ExecutionState:
    def __init__(self):
        self.successes = []
        self.failures = {}
        self.validation_failures = {}
        self.attempt_counts = {}
        self.rejected_call_ids = set()
        self.deferred_call_ids = set()
        self.schema_loads = []
        self.skipped_actions = []

    def record_skipped(self, call, reason):
        self.skipped_actions.append(
            {
                "call_id": call["id"],
                "tool": call["tool"],
                "reason": reason,
                "action_executed": False,
            }
        )

    def record_deferred(self, call):
        self.deferred_call_ids.add(call["id"])
        self.schema_loads.append(
            {
                "call_id": call["id"],
                "tool": call["tool"],
                "status": "schema_ready",
                "action_executed": False,
            }
        )

    def record(self, call, success, output, *, validation=False, generated=None):
        name = call["tool"]
        counts = self.attempt_counts.setdefault(name, {"successful": 0, "failed": 0})
        counts["successful" if success else "failed"] += 1
        item = {"call_id": call["id"], "tool": name}
        coder = None
        if name == "delegate_to_coder":
            try:
                coder = coder_result_data(json.loads(str(output)))
            except (TypeError, ValueError):
                pass
            if coder:
                item["coder_outcome"] = coder["execution_outcome"]
        if success:
            item["result"] = result_metadata(output, generated)
            self.successes.append(item)
            self.failures.pop(name, None)
            self.validation_failures[name] = 0
        else:
            # Parsing diagnostics may append the whole rejected payload;
            # traces retain it, but the decision ledger needs only the error.
            item["error"] = str(output).split("; received ", 1)[0][:2000]
            item["kind"] = "validation" if validation else "execution"
            if coder:
                item["error"] = coder["summary_excerpt"]
            self.failures[name] = item
            if validation:
                self.rejected_call_ids.add(call["id"])
                self.validation_failures[name] = (
                    self.validation_failures.get(name, 0) + 1
                )

    def message(self):
        if (
            not self.successes
            and not self.failures
            and not self.schema_loads
            and not self.skipped_actions
        ):
            return None
        data = {
            "successful_actions": self.successes,
            "latest_failures": list(self.failures.values()),
            "attempt_counts": self.attempt_counts,
        }
        if self.schema_loads:
            data["schema_loads"] = self.schema_loads
        if self.skipped_actions:
            data["skipped_actions"] = self.skipped_actions
        message = untrusted_context_message(
            "application execution ledger for the current request",
            format_prompt(
                "agent_execution_state",
                state=json.dumps(data, ensure_ascii=False, separators=(",", ":")),
            ),
        )
        message["metadata"]["agent_context"] = True
        message["metadata"]["agent_execution_state"] = True
        return message
